package com.smartresponse.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="relief_requests") public class ReliefRequest {@Id @GeneratedValue private UUID id;private String requestType;private int peopleCount;private String description;private double latitude;private double longitude;private String requestStatus="OPEN";@Column(name="reporter_id") private UUID reporterId;private Instant createdAt=Instant.now();protected ReliefRequest(){}public ReliefRequest(String t,int p,String d,double lat,double lon,UUID rid){requestType=t;peopleCount=p;description=d;latitude=lat;longitude=lon;reporterId=rid;}public UUID getId(){return id;}public String getRequestStatus(){return requestStatus;}public String getRequestType(){return requestType;}public int getPeopleCount(){return peopleCount;}public String getDescription(){return description;}public UUID getReporterId(){return reporterId;}public Instant getCreatedAt(){return createdAt;}}
